// Indexing Maps
const DELHI_PROJECTS_BY_SLUG = new Map();
DELHI_REGISTRY_PROJECTS.forEach((p) => {
  DELHI_PROJECTS_BY_SLUG.set(p.slug.toLowerCase(), p);
  DELHI_PROJECTS_BY_SLUG.set(String(p.id), p);
  if (p.sourceId) {
    DELHI_PROJECTS_BY_SLUG.set(String(p.sourceId), p);
  }
});

// All registered Delhi slugs
export const DELHI_ALL_SLUGS = DELHI_REGISTRY_PROJECTS.map((p) => p.slug);

// Coordinates map for Leaflet / OpenStreetMap
export const DELHI_PROJECT_COORDINATES = {};
DELHI_REGISTRY_PROJECTS.forEach((p) => {
  if (p.lat && p.lng) {
    DELHI_PROJECT_COORDINATES[p.slug] = {
      lat: p.lat,
      lng: p.lng,
      locality: p.location,
      city: "delhi",
      cityName: "Delhi NCR",
      propertyType: p.type || "Apartment",
      verified: true
    };
    DELHI_PROJECT_COORDINATES[p.id] = DELHI_PROJECT_COORDINATES[p.slug];
  }
});

// Standard floor plan generator helper for dynamic detail pages
function generateFloorPlansForDelhiProject(p) {
  const typologies = (p.flatTypes || "2, 3 BHK").toLowerCase();
  const plans = [];

  if (typologies.includes("1 bhk") || typologies.includes("1bhk") || typologies.includes("1,")) {
    plans.push({
      type: "1 BHK Smart Suite",
      bhk: "1 BHK",
      carpetArea: "450 - 550 sq.ft",
      superArea: "650 - 780 sq.ft",
      price: p.priceNumeric ? `₹ ${(p.priceNumeric * 0.55 / 10000000).toFixed(2)} Cr*` : "On Request",
      specs: { bedrooms: 1, bathrooms: 1, balconies: 1, parking: "1 Covered" },
      facing: "East / Park Facing",
      description: "Efficient urban apartment layout optimized for modern professionals, featuring open kitchenette, living deck, and en-suite bath.",
      layoutImage: "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (typologies.includes("2 bhk") || typologies.includes("2bhk") || typologies.includes("2,")) {
    plans.push({
      type: "2 BHK Premium",
      bhk: "2 BHK",
      carpetArea: "750 - 950 sq.ft",
      superArea: "1,050 - 1,350 sq.ft",
      price: p.price ? `₹ ${p.price}*` : "On Request",
      specs: { bedrooms: 2, bathrooms: 2, balconies: 2, parking: "1 Covered" },
      facing: "North-East / Vastu Compliant",
      description: "Well-ventilated master bedroom with en-suite bath, dedicated dining alcove, utility balcony, and wide sundeck.",
      layoutImage: "https://images.unsplash.com/photo-1600566753376-12c8ab7fb75b?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (typologies.includes("3 bhk") || typologies.includes("3bhk") || typologies.includes("3,")) {
    plans.push({
      type: "3 BHK Grande",
      bhk: "3 BHK",
      carpetArea: "1,250 - 1,650 sq.ft",
      superArea: "1,750 - 2,300 sq.ft",
      price: p.priceNumeric ? `₹ ${(p.priceNumeric * 1.3 / 10000000).toFixed(2)} Cr*` : "On Request",
      specs: { bedrooms: 3, bathrooms: 3, balconies: 3, parking: "2 Covered" },
      facing: "Skyline / Club Facing",
      description: "Expansive living-dining salon, walk-in wardrobe in master suite, imported marble foyer, and separate servant quarter.",
      layoutImage: "https://images.unsplash.com/photo-1600596542815-ffad4c1539a9?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (typologies.includes("4 bhk") || typologies.includes("4bhk") || typologies.includes("4,") || typologies.includes("5 bhk") || typologies.includes("6 bhk")) {
    plans.push({
      type: "4 BHK Royal Penthouse",
      bhk: "4 BHK",
      carpetArea: "2,100 - 3,200 sq.ft",
      superArea: "3,000 - 4,500 sq.ft",
      price: p.priceNumeric ? `₹ ${(p.priceNumeric * 1.8 / 10000000).toFixed(2)} Cr*` : "On Request",
      specs: { bedrooms: 4, bathrooms: 4, balconies: 4, parking: "3 Covered" },
      facing: "Panoramic 270° Views",
      description: "Palatial family residence with double-height ceiling deck, family lounge, and lavish master penthouse suite.",
      layoutImage: "https://images.unsplash.com/photo-1600607687939-ce8a6c25118c?auto=format&fit=crop&w=800&q=80"
    });
  }

  if (plans.length === 0) {
    plans.push({
      type: "Standard Residence",
      bhk: p.flatTypes || "3 BHK",
      carpetArea: p.carpetArea || "1,100 - 1,500 sq.ft",
      superArea: "1,550 - 2,100 sq.ft",
      price: p.price || "On Request",
      specs: { bedrooms: 3, bathrooms: 3, balconies: 2, parking: "2 Covered" },
      facing: "Vastu Compliant",
      description: "Optimal carpet-to-super-area layout with expansive windows, modular kitchen provision, and branded bathroom fittings.",
      layoutImage: "https://images.unsplash.com/photo-1600585154340-be6161a56a0c?auto=format&fit=crop&w=800&q=80"
    });
  }

  return plans;
}

// Resolver for Delhi Project Detail Pages
export function getDelhiProjectBySlug(rawSlug) {
  if (!rawSlug) return null;
  const clean = String(rawSlug).toLowerCase().trim();
  const p = DELHI_PROJECTS_BY_SLUG.get(clean);
  if (!p) return null;

  // Convert features to structured amenities array for the UI
  const amenitiesList = (p.features || ["24/7 Security", "Clubhouse", "Swimming Pool"]).map((feat) => {
    let cat = "Lifestyle";
    let icon = "Sparkles";
    const fLower = feat.toLowerCase();
    if (fLower.includes("pool") || fLower.includes("water")) { cat = "Wellness"; icon = "Waves"; }
    else if (fLower.includes("gym") || fLower.includes("fit") || fLower.includes("yoga")) { cat = "Fitness"; icon = "Activity"; }
    else if (fLower.includes("club") || fLower.includes("hall") || fLower.includes("deck")) { cat = "Lifestyle"; icon = "Building2"; }
    else if (fLower.includes("security") || fLower.includes("cctv") || fLower.includes("gate")) { cat = "Security"; icon = "ShieldCheck"; }
    else if (fLower.includes("kid") || fLower.includes("play")) { cat = "Kids"; icon = "Smile"; }
    else if (fLower.includes("garden") || fLower.includes("tree") || fLower.includes("ev")) { cat = "Eco"; icon = "Zap"; }
    else if (fLower.includes("court") || fLower.includes("sport") || fLower.includes("track")) { cat = "Sports"; icon = "Trophy"; }

    return {
      name: feat,
      category: cat,
      icon: icon
    };
  });

  // Highlights
  const highlights = [
    `Prime address in ${p.location}`,
    `Developed by Grade-A builder ${p.builder}`,
    p.rera && p.rera !== "Not Available" ? `RERA Registered: ${p.rera}` : "Transparent documentation and verified compliance",
    `Available Configurations: ${p.flatTypes}`,
    `Possession: ${p.possession}`,
    "Direct builder allotment with zero brokerage through AuraLiving"
  ];

  // Nearby landmarks
  const landmarks = [
    { name: `${p.locality} Transit Junction`, distance: "0.8 km", time: "3 mins", type: "Transit" },
    { name: "Delhi Metro Station", distance: "1.2 km", time: "4 mins", type: "Transit" },
    { name: "Expressway / Ring Road Access", distance: "2.0 km", time: "6 mins", type: "Road" },
    { name: "Super-Speciality Hospital", distance: "3.2 km", time: "9 mins", type: "Healthcare" },
    { name: "Leading International School", distance: "2.5 km", time: "7 mins", type: "Education" },
    { name: "IGI Airport Terminal", distance: "12.0 km", time: "20 mins", type: "Airport" }
  ];

  // Developer info
  const developerInfo = {
    name: p.builder,
    slug: p.developerSlug,
    logo: p.builderLogo,
    experience: "25+ Years",
    projectsCount: "30+ Projects",
    established: "1995",
    description: `${p.builder} is recognized for architectural distinction, quality construction, and timely delivery across Delhi NCR.`
  };

  // 3-4 related slugs in Delhi
  const otherDelhi = DELHI_REGISTRY_PROJECTS.filter((item) => item.slug !== p.slug);
  const relatedSlugs = otherDelhi.slice(0, 4).map((item) => item.slug);

  return {
    id: p.id,
    sourceId: p.sourceId,
    slug: p.slug,
    title: p.name,
    name: p.name,
    builder: p.builder,
    developerSlug: p.developerSlug,
    developerInfo: developerInfo,
    city: "delhi",
    cityName: "Delhi NCR",
    region: p.region,
    locality: p.locality,
    location: p.location,
    fullAddress: p.fullAddress,
    price: p.price,
    priceNumeric: p.priceNumeric,
    avgPrice: p.avgPrice,
    flatTypes: p.flatTypes,
    carpetArea: p.carpetArea,
    possession: p.possession,
    rera: p.rera,
    rera_informations: p.rera_informations,
    status: p.status,
    tag: p.tag,
    rating: p.rating,
    reviewsCount: 88,
    images: p.images,
    overview: p.description,
    highlights: highlights,
    amenities: amenitiesList,
    floorPlans: generateFloorPlansForDelhiProject(p),
    landmarks: landmarks,
    lat: p.lat,
    lng: p.lng,
    relatedProjectSlugs: relatedSlugs,
    referenceUrl: p.referenceUrl
  };
}
